from pwn import *
import sys

HOST = "rev.chal.csaw.io"
PORT = 4200

# Settings
total_rounds = 21
bet_color = 'green'
bet_amount = '1'  # minimum

log_lines = []

def logrecv(data, label="RECV"):
    try:
        if isinstance(data, bytes):
            data = data.decode(errors='replace')
        data = data.replace('\r', '')
    except Exception as e:
        data = str(data)
    line = f"[{label}] {data}"
    print(line, flush=True)
    log_lines.append(line)

def logsend(data, label="SEND"):
    line = f"[{label}] {data}"
    print(line, flush=True)
    log_lines.append(line)

def main():
    io = remote(HOST, PORT)
    io.recvtimeout = 2

    # Read all banner/setup lines initially
    try:
        while True:
            line = io.recvline(timeout=2)
            if not line:
                break
            logrecv(line, label='BANNER')
    except EOFError:
        pass
    except Exception:
        pass

    # Play through betting rounds
    for i in range(total_rounds):
        try:
            # Read prompt(s) leading to color selection
            for _ in range(3):
                line = io.recvline(timeout=2)
                if not line: continue
                logrecv(line, label=f'ROUND{i+1}/PROMPT')
        except Exception as e:
            logrecv(f'Exception on round {i+1} wait: {e}', 'ERR')
            break

        # Send color selection
        io.sendline(bet_color)
        logsend(bet_color, label=f'ROUND{i+1}/SENDCOLOR')

        try:
            line = io.recvline(timeout=2)
            logrecv(line, label=f'ROUND{i+1}/AFTERCOLOR')
        except Exception as e:
            logrecv(f'After color send line exception {e}', 'ERRC')
            break

        # Send the minimum bet amount
        io.sendline(bet_amount)
        logsend(bet_amount, label=f'ROUND{i+1}/SENDBET')

        # Fetch all expected output for the result of this round
        more = True
        while more:
            try:
                line = io.recvline(timeout=2)
                if not line:
                    more = False
                else:
                    logrecv(line, label=f'ROUND{i+1}/POSTBET')
            except Exception:
                more = False

    # Try to read any final lines
    try:
        while True:
            line = io.recvline(timeout=2)
            if not line:
                break
            logrecv(line, label='FINAL')
    except Exception:
        pass
    io.close()

    # Write log to file for attaching/summary
    with open('/home/ctfplayer/ctf_files/roulette_full_interaction.log', 'w') as f:
        for line in log_lines:
            f.write(line + "\n")

if __name__ == '__main__':
    main()

